    W + " .zcc-result.fail{" +
      "background:linear-gradient(135deg," + cfg.errorColor + "08," + cfg.errorColor + "14) !important;" +
      "border:1px solid " + cfg.errorColor + "30 !important;color:" + cfg.errorColor + " !important" +
    "}" +

    // Result icon container
    W + " .zcc-result-icon{" +
      "flex-shrink:0 !important;width:24px !important;height:24px !important;display:flex !important;align-items:center !important;justify-content:center !important" +
    "}" +
    W + " .zcc-result-icon svg{width:22px !important;height:22px !important}" +
    W + " .zcc-result-content{flex:1 !important;min-width:0 !important}" +

    // Meta info lines
    W + " .zcc-meta{" +
      "margin-top:6px !important;font-size:13px !important;opacity:.85 !important;" +
      "display:flex !important;align-items:center !important;gap:6px !important" +
    "}" +
    W + " .zcc-meta svg{width:14px !important;height:14px !important;flex-shrink:0 !important}" +

    // Specific meta classes
    W + " .zcc-cutoff{margin-top:6px !important;font-size:0.85em !important;color:#6d7175 !important;display:flex !important;align-items:center !important;gap:6px !important}" +
    W + " .zcc-days{margin-top:6px !important;font-size:0.85em !important;color:#6d7175 !important;display:flex !important;align-items:center !important;gap:6px !important}" +
    W + " .zcc-cod{margin-top:6px !important;font-size:0.85em !important;font-weight:500 !important;display:flex !important;align-items:center !important;gap:6px !important}" +
    W + " .zcc-cod--available{color:#008060 !important}" +
    W + " .zcc-cod--unavailable{color:#d72c0d !important}" +
    W + " .zcc-return-policy{margin-top:6px !important;font-size:0.85em !important;color:#6d7175 !important;display:flex !important;align-items:center !important;gap:6px !important}" +

    // Waitlist section
    W + " .zcc-wl{margin-top:14px !important;padding:14px !important;background:" + cfg.errorColor + "06 !important;border-radius:" + rad + " !important}" +
    W + " .zcc-wl-toggle{" +
      "display:inline-flex !important;align-items:center !important;gap:6px !important;" +
      "font-size:13px !important;font-weight:600 !important;color:" + cfg.primaryColor + " !important;" +
      "text-decoration:none !important;cursor:pointer !important;border:none !important;background:none !important;padding:0 !important" +
    "}" +
    W + " .zcc-wl-toggle:hover{text-decoration:underline !important}" +
    W + " .zcc-wl-input{" +
      "width:100% !important;padding:10px 12px !important;border:1px solid #e1e3e5 !important;" +
      "border-radius:" + rad + " !important;font-size:13px !important;margin-bottom:8px !important;" +
      "display:block !important;outline:none !important;transition:border-color 0.2s !important" +
    "}" +
    W + " .zcc-wl-input:focus{border-color:" + cfg.primaryColor + " !important;box-shadow:0 0 0 2px " + cfg.primaryColor + "20 !important}" +
    W + " .zcc-wl-btn{" +
      "background:" + cfg.primaryColor + " !important;color:#fff !important;border:none !important;" +
      "border-radius:" + rad + " !important;padding:10px 16px !important;font-size:13px !important;" +
      "cursor:pointer !important;width:100% !important;font-weight:600 !important;" +
      "transition:all 0.2s ease !important" +
    "}" +
    W + " .zcc-wl-btn:hover{filter:brightness(1.08) !important}" +
    W + " .zcc-wl-btn:disabled{opacity:.6 !important;cursor:not-allowed !important}" +

    // Social proof badge
    W + " .zcc-social-proof{" +
      "display:inline-flex !important;align-items:center !important;gap:6px !important;" +
      "font-size:12px !important;color:#6d7175 !important;margin-bottom:10px !important;" +
      "background:#f6f6f7 !important;padding:4px 10px !important;border-radius:20px !important" +
    "}" +

    // Mobile responsive
    "@media(max-width:480px){" +
      W + "{padding:16px !important}" +
      W + " .zcc-heading{font-size:15px !important;margin:0 0 16px !important}" +
      W + " .zcc-search-bar{flex-direction:column !important;border-radius:" + rad + " !important}" +
      W + " .zcc-btn{border-left:none !important;border-top:1px solid " + cfg.primaryColor + " !important}" +
      W + " .zcc-result{flex-direction:column !important;gap:8px !important}" +
    "}" +

    // Scoped custom CSS
    scopeCustomCss(cfg.customCss, wid);

  var styleEl = document.createElement("style");
  styleEl.textContent = css;
  document.head.appendChild(styleEl);
}

