        "background:transparent !important;color:" + cfg.textColor + " !important;min-width:0 !important" +
      "}" +
      W + " .zcc-input::placeholder{color:#8c9196 !important}" +

      // Button — right side of search bar
      W + " .zcc-btn{" +
