      "}" +

      // Result icon container
      W + " .zcc-result-icon{" +
        "flex-shrink:0 !important;width:24px !important;height:24px !important;display:flex !important;align-items:center !important;justify-content:center !important" +
      "}" +
      W + " .zcc-result-icon svg{width:22px !important;height:22px !important}" +
      W + " .zcc-result-content{flex:1 !important;min-width:0 !important}" +

      // Meta info lines
      W + " .zcc-meta{" +
        "margin-top:6px !important;font-size:13px !important;opacity:.85 !important;" +
        "display:flex !important;align-items:center !important;gap:6px !important" +
      "}" +
      W + " .zcc-meta svg{width:14px !important;height:14px !important;flex-shrink:0 !important}" +

      // Specific meta classes
      W + " .zcc-cutoff{margin-top:6px !important;font-size:0.85em !important;color:#6d7175 !important;display:flex !important;align-items:center !important;gap:6px !important}" +
