        W + " .zcc-search-bar{flex-direction:column !important;border-radius:" + rad + " !important}" +
        W + " .zcc-btn{border-left:none !important;border-top:1px solid " + cfg.primaryColor + " !important}" +
        W + " .zcc-result{flex-direction:column !important;gap:8px !important}" +
