  const resultClass =
    previewState === "success" ? "ok" :
    (previewState === "error" || previewState === "notfound") ? "fail" : "";

  const resultMessage =
    previewState === "success" ? cfg.successMessage :
    previewState === "error" ? cfg.errorMessage :
