      <>
        {/* eslint-disable-next-line react/no-danger */}
        <style dangerouslySetInnerHTML={{ __html: css }} />
        <div
          style={{
            position: "relative",
            minHeight: "120px",
            background: "#f6f6f7",
            borderRadius: "8px",
            padding: "12px",
