                />
                <button className="zcc-btn" type="button">
                  {cfg.buttonText}
                </button>
              </div>
            </div>
            <button
              type="button"
              style={{
                background: cfg.primaryColor,
                color: "#fff",
                border: "none",
                borderRadius: "50px",
                padding: "10px 18px",
                fontSize: "13px",
                fontWeight: 600,
                cursor: "pointer",
                boxShadow: "0 4px 12px rgba(0,0,0,.2)",
              }}
            >
              📍 Check Delivery
            </button>
          </div>
        </div>
      </>
    );
  }

  // Popup position: show trigger button + hint of overlay
  if (cfg.position === "popup") {
    return (
      <>
        {/* eslint-disable-next-line react/no-danger */}
        <style dangerouslySetInnerHTML={{ __html: css }} />
        <div style={{ display: "flex", flexDirection: "column", gap: "12px" }}>
          <Text as="p" variant="bodySm" tone="subdued">
            A trigger button will appear in the section. Clicking it opens a centered popup.
          </Text>
          <div>
            <button
              type="button"
              style={{
                background: cfg.primaryColor,
                color: "#fff",
                border: "none",
                borderRadius: cfg.borderRadius + "px",
                padding: "10px 24px",
                fontSize: "14px",
                fontWeight: 600,
                cursor: "pointer",
              }}
            >
              Check Delivery Availability
            </button>
          </div>
          <div
            style={{
              background: "rgba(0,0,0,.06)",
              borderRadius: "8px",
              padding: "12px",
              border: "2px dashed #c9cccf",
            }}
          >
            <Text as="p" variant="bodySm" tone="subdued">
              Popup content preview:
            </Text>
            <div style={{ marginTop: "8px" }}>{widgetHtml}</div>
          </div>
        </div>
      </>
    );
  }

  // Inline (default)
  return (
    <>
      {/* eslint-disable-next-line react/no-danger */}
      <style dangerouslySetInnerHTML={{ __html: css }} />
      {widgetHtml}
    </>
  );
}

