    "}" +
    W + " *{box-sizing:border-box}" +

    // Heading with icon
    W + " .zcc-heading{font-size:17px;font-weight:700;letter-spacing:-0.01em;margin:0 0 20px;color:" + cfg.textColor + ";display:flex;align-items:center;gap:8px}" +
